/* eslint-disable complexity */
import {getBaseSiteId, getLanguage} from '@smart/locale-service';
import {parseAdbContextCookie, parseLoginUserDetailsCookie} from '@smart/utils';
import type {APIGatewayProxyHandler, APIGatewayProxyResult} from 'aws-lambda';
import type {CustomerConsents} from '../../el-web-client';
import {ElWebClient} from '../../el-web-client';
import {fetchEndpointDirectory} from '../../fetch-endpoint-directory';
import {getApiEndpoint, getApiHeaders} from '../../utils/api-endpoint';
import {decodeEventBody} from '../../utils/aws-event';
import {handleError} from '../../utils/error-handler';
import {isMockError, simulateDelay} from '../../utils/mocks';
import {coerceQueryParams} from '../coerce-query-params';
import {coerceBodyParams} from './coerce-body-params';
import type {ConsentsChange} from './coerce-body-params';

export const handler: APIGatewayProxyHandler = async (
  event,
  {awsRequestId},
): Promise<APIGatewayProxyResult> => {
  const queryParams = coerceQueryParams(event.queryStringParameters || {});
  const {
    mock,
    marketId,
    languageTag,
    preview,
    envName,
    rotatingVerifySecret,
    enableConsents,
  } = queryParams;

  const consentsChange = coerceBodyParams(
    JSON.parse(decodeEventBody(event) || `{}`),
  );
  if (!consentsChange) {
    return {
      statusCode: 400,
      headers: {'X-Lambda-Request-Id': awsRequestId},
      body: `missing or invalid POST body`,
    };
  }

  const userDetails = parseLoginUserDetailsCookie(
    event.headers.Cookie ?? event.headers.cookie ?? ``,
  );

  if (!userDetails) {
    return {
      statusCode: 401,
      headers: {'X-Lambda-Request-Id': awsRequestId},
      body: `Unauthorized`,
    };
  }

  const adbContext = parseAdbContextCookie(
    event.headers.Cookie ?? event.headers.cookie ?? ``,
  );

  if (adbContext) {
    return {
      statusCode: 400,
      headers: {'X-Lambda-Request-Id': awsRequestId},
      body: `Not possible in ADB context`,
    };
  }

  if (mock) {
    await simulateDelay();
    if (isMockError(consentsChange)) {
      return {
        statusCode: 500,
        headers: {
          'X-Lambda-Request-Id': awsRequestId,
          'Content-Type': `application/json`,
        },
        body: JSON.stringify({status: `error`}),
      };
    }

    return {
      statusCode: 200,
      headers: {
        'X-Lambda-Request-Id': awsRequestId,
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
      body: JSON.stringify({status: `success`}),
    };
  }
  if (enableConsents) {
    try {
      const apiEndpoint = getApiEndpoint(envName);
      const apiHeaders = getApiHeaders();

      const hasPhoneConsent =
        consentsChange.consentPhone || consentsChange.consentVocPhone;

      const consentGranted = [
        consentsChange.consentDirectMail && `smart_marketingConsentPostal_EU`,
        consentsChange.consentEmail && `smart_marketingConsentEmail_EU`,
        consentsChange.consentPhone && `smart_marketingConsentPhone_EU`,
        consentsChange.consentVocPhone && `smart_vocConsentPhone_EU`,
        consentsChange.consentVocEmail && `smart_vocConsentEmail_EU`,
      ].filter(Boolean);

      const signal = {
        method: `PUT`,
        body: JSON.stringify({
          UID: userDetails.uid,
          consentGranted,
          // only send address if consentDirectMail and address info is provided
          ...(consentsChange.consentDirectMail &&
            consentsChange.street && {
              address: {
                street: consentsChange.street,
                city: consentsChange.city,
                postalCode: consentsChange.postalCode,
              },
            }),
          // only send phone if consentPhone or consentVocPhone and verifiedPhone is provided
          ...(hasPhoneConsent &&
            consentsChange.verifiedPhone && {
              verifiedPhone: consentsChange.verifiedPhone,
            }),
        }),
        headers: apiHeaders,
      };

      const url = `${apiEndpoint}/cdc/v1/update-consent`;
      const response = await fetch(url, signal);
      if (!response.ok) {
        const errorCode = response.status;
        throw Error(
          `${errorCode}: Could not edit consents. Please try again later.`,
        );
      }
      const responseData = await response.json();

      return {
        statusCode: responseData.statusCode || 200,
        headers: {
          'X-Lambda-Request-Id': awsRequestId,
          'Content-Type': `application/json`,
          'Cache-Control': `private, no-store`,
        },
        body: JSON.stringify({status: responseData?.statusReason || `success`}),
      };
    } catch (error: any) {
      return handleError(error, awsRequestId);
    }
  }
  try {
    const {mulesoft} = await fetchEndpointDirectory({
      envName,
      preview,
      rotatingVerifySecret,
    });

    if (!mulesoft) {
      return {
        statusCode: 500,
        headers: {'X-Lambda-Request-Id': awsRequestId},
        body: `Unable to fetch mulesoft endpoint`,
      };
    }

    const preferences: CustomerConsents['preferences'] = hasConsents(
      consentsChange,
    )
      ? [
          {
            name: `smart_consentDirectMail_EU`,
            isConsentGranted: consentsChange.consentDirectMail,
          },
          {
            name: `smart_consentEmail_EU`,
            isConsentGranted: consentsChange.consentEmail,
          },
          {
            name: `smart_consentPhone_EU`,
            isConsentGranted: consentsChange.consentPhone,
          },
        ]
      : undefined;
    const subscriptions: CustomerConsents['subscriptions'] = hasSubscription(
      consentsChange,
    )
      ? [
          {
            name: consentsChange.organisationId
              ? `smart_B2B_NLwithDOI_EU`
              : `smart_NLwithDOI_EU`,
            isSubscribed: consentsChange.newsletter,
          },
        ]
      : undefined;

    const baseSiteId = getBaseSiteId(marketId);
    const language = getLanguage(languageTag);
    const elWeb = new ElWebClient(mulesoft, baseSiteId, language);
    const response = await elWeb.saveCustomerConsents(
      {
        preferences,
        subscriptions,
      },
      userDetails,
    );

    return {
      statusCode: response?.code || 200,
      headers: {
        'X-Lambda-Request-Id': awsRequestId,
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
      body: JSON.stringify({status: response?.info || `success`}),
    };
  } catch (error: any) {
    return handleError(error, awsRequestId);
  }
};
const hasConsents = (consentsChange: ConsentsChange): boolean => {
  return (
    consentsChange.consentDirectMail !== undefined ||
    consentsChange.consentEmail !== undefined ||
    consentsChange.consentPhone !== undefined
  );
};

const hasSubscription = (consentsChange: ConsentsChange): boolean => {
  return consentsChange.newsletter !== undefined;
};

