import {getBaseSiteId, getLanguage} from '@smart/locale-service';
import {parseAdbContextCookie, parseLoginUserDetailsCookie} from '@smart/utils';
import type {APIGatewayProxyHandler, APIGatewayProxyResult} from 'aws-lambda';
import type {Consents} from '../../feature-app/utils/fetch-consents';
import {type CustomerConsents, ElWebClient} from '../el-web-client';
import {fetchEndpointDirectory} from '../fetch-endpoint-directory';
import {getApiEndpoint, getApiHeaders} from '../utils/api-endpoint';
import {handleError} from '../utils/error-handler';
import {simulateDelay} from '../utils/mocks';
import {coerceQueryParams} from './coerce-query-params';
import mockData from './mock.json';

export const handler: APIGatewayProxyHandler = async (
  event,
  {awsRequestId},
): Promise<APIGatewayProxyResult> => {
  const queryParams = coerceQueryParams(event.queryStringParameters || {});
  const {
    organisationId,
    mock,
    marketId,
    languageTag,
    preview,
    envName,
    rotatingVerifySecret,
    enableConsents,
  } = queryParams;

  const userDetails = parseLoginUserDetailsCookie(
    event.headers.Cookie ?? event.headers.cookie ?? ``,
  );

  if (!userDetails) {
    return {
      statusCode: 401,
      headers: {'X-Lambda-Request-Id': awsRequestId},
      body: `Unauthorized`,
    };
  }

  const adbContext = parseAdbContextCookie(
    event.headers.Cookie ?? event.headers.cookie ?? ``,
  );

  if (adbContext) {
    return {
      statusCode: 400,
      headers: {'X-Lambda-Request-Id': awsRequestId},
      body: `Not possible in ADB context`,
    };
  }

  if (mock) {
    await simulateDelay();

    return {
      statusCode: 200,
      headers: {
        'X-Lambda-Request-Id': awsRequestId,
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
      body: JSON.stringify(mockData),
    };
  }
  if (enableConsents) {
    try {
      const apiEndpoint = getApiEndpoint(envName);
      const apiHeaders = getApiHeaders();

      const urlParams = new URLSearchParams({
        UID: userDetails.uid,
        extraProfileFields: `phones`,
      });

      const signal = {
        method: `GET`,
        headers: apiHeaders,
      };

      const url = `${apiEndpoint}/cdc/v1/account-info?${urlParams.toString()}`;

      console.info(userDetails.uid, process.env.AWS_API_KEY, url);
      const response = await fetch(url, signal);
      if (!response.ok) {
        const errorCode = response.status;
        throw Error(`${errorCode}: Could not fetch account info`);
