changeList.full_content:
import type {ConsentsChange} from '../../bff/consents/edit/coerce-body-params';
import type {FetchFromBFFOptions} from './fetch-params';
import {createFetchSearchParams} from './fetch-params';
import {convertToPrivate} from './private-base-url';

export interface ConsentsData {
  consents: Consents;
}

export interface Consents {
  consentVocPhone?: boolean;
  consentVocEmail?: boolean;
  consentPhone?: boolean;
  termsOfService?: boolean;
  consentDirectMail?: boolean;
  consentEmail?: boolean;
  privacyPolicy?: boolean;
  newsletter?: boolean;
  verifiedPhone?: string;
}

export async function fetchConsents(
  baseUrl: string = ``,
  options: FetchFromBFFOptions,
  organisationId?: string,
  enableConsents?: boolean,
): Promise<ConsentsData> {
  const searchParams = createFetchSearchParams(options);
  const {signal} = options;

  if (organisationId) {
    searchParams.set(`organisationId`, organisationId);
  }
  if (enableConsents) {
    searchParams.set(`enableConsents`, String(enableConsents));
  }

  const url = `${convertToPrivate(
    baseUrl,
  )}/bff/consents?${searchParams.toString()}`;
  const response = await fetch(url, signal ? {signal} : undefined);

  if (!response.ok) {
    throw Error(`Could not fetch consents.`);
  }

  return response.json() as Promise<ConsentsData>;
}

export async function postConsents(
  data: ConsentsChange,
  baseUrl: string = ``,
  options: FetchFromBFFOptions,
): Promise<any> {
  const searchParams = createFetchSearchParams(options);

  const url = `${convertToPrivate(
    baseUrl,
  )}/bff/consents?${searchParams.toString()}`;
  const response = await fetch(url, {
    method: `POST`,
    headers: {'Content-Type': `application/json`},
    body: JSON.stringify(data),
  });

  if (!response.ok) {
    throw Error(`Could not post consents.`);
  }

  return response.json() as Promise<any>;
}
